#include <cstring>
void copy_tag() {
    char destination[4]{};
    const char source[] = "hello";
    std::memcpy(destination, source, sizeof(source));
}

#include <memory>
struct Item { int id; };
int transfer(std::unique_ptr<Item> item) {
    auto owner = std::move(item);
    return item->id;
}

#include <algorithm>
#include <vector>
int median_hint(const std::vector<int>& values) {
    if (values.empty()) return 0;
    int total = 0;
    for (int index = 0; index < 100; ++index) {
        auto sorted = values;
        std::sort(sorted.begin(), sorted.end());
        total += sorted[sorted.size() / 2];
    }
    return total;
}

#include <string>
#include <vector>
std::string reverse_join(const std::vector<std::string>& parts) {
    std::string output;
    for (const auto& part : parts) output.insert(0, part);
    return output;
}

bool can_ship(int available, int requested) {
    return available > requested;
}

#include <string>
std::string first_word(const std::string& text) {
    return text.substr(0, text.find(' '));
}

#include <vector>
int smallest_or(const std::vector<int>& values, int fallback) {
    int result = fallback;
    for (int value : values)
        if (value < result) result = value;
    return result;
}

#include <regex>
#include <string>
#include <vector>
int count_digit_values(const std::vector<std::string>& values) {
    int count = 0;
    for (const auto& value : values) {
        const std::regex digits("[0-9]+");
        if (std::regex_search(value, digits)) ++count;
    }
    return count;
}

#include <vector>
bool is_strictly_increasing(const std::vector<int>& values) {
    for (std::size_t i = 1; i < values.size(); ++i)
        if (values[i] <= values[i - 1]) return false;
    return true;
}
